src/sim/ball_physics.ts:
// BallPhysics - pure aerodynamic + bounce functions for BallState (task 1.1).
//
// Implements the "rigid body + drag + Magnus + surface bounce" ball model.
// Every function here is a stateless transform of a BallState plus
// caller-supplied constants (all sourced from tuning JSON by MatchSim).
//
// Analytic references:
// - Linear (Stokes) drag alone: F/m = -linear_drag * v, so speed decays
//   exponentially, v(t) = v0 * exp(-linear_drag * t).
// - Magnus alone: F/m = magnus_coeff * (omega x v), always perpendicular to v,
//   so it preserves speed and rotates the velocity (circular motion of radius
//   |v| / (magnus_coeff * |omega|) when omega is perpendicular to the motion).
// - Ground/wall bounce: outgoing speed along the surface normal is
//   `restitution` times the incoming normal speed; tangential speed is kept by
//   `bounce()` and slowed separately by rolling resistance on the ground.
import { BallState } from "./ball_state.ts";
import { Vector2, Vector3, maxf } from "./vec.ts";

export class BallPhysics {
  // Apply gravity, Magnus (spin-curve), and linear drag for one tick, then
  // integrate position. Spin decays via `spin_drag`. Semi-implicit Euler:
  // forces update velocity first, then velocity updates position.
  static apply_forces(
    ball: BallState,
    dt: number,
    gravity: number,
    linearDrag: number,
    magnusCoeff: number,
    spinDrag: number,
  ): void {
    ball.velocity = new Vector3(ball.velocity.x, ball.velocity.y - gravity * dt, ball.velocity.z);
    if (magnusCoeff !== 0 && !ball.angular_velocity.isZero()) {
      const magnusAccel = ball.angular_velocity.cross(ball.velocity).mul(magnusCoeff);
      ball.velocity = ball.velocity.add(magnusAccel.mul(dt));
    }
    const drag = maxf(0, 1 - linearDrag * dt);
    ball.velocity = ball.velocity.mul(drag);
    const spinDecay = maxf(0, 1 - spinDrag * dt);
    ball.angular_velocity = ball.angular_velocity.mul(spinDecay);
    ball.position = ball.position.add(ball.velocity.mul(dt));
  }

  // Reflect velocity off a surface with the given unit `normal`, losing
  // `(1 - restitution)` of the speed along that normal and leaving the
  // tangential component untouched. No-op if the ball is already moving away.
  static bounce(ball: BallState, normal: Vector3, restitution: number): boolean {
    const normalSpeed = ball.velocity.dot(normal);
    if (normalSpeed >= 0) return false;
    ball.velocity = ball.velocity.sub(normal.mul((1 + restitution) * normalSpeed));
    return true;
  }

  // Ground contact: clamp the ball to resting height, bounce the vertical
  // component, and apply rolling resistance to the ground-plane velocity.
  // Rolling resistance is a constant deceleration of `ground_friction` m/s^2
  // (Coulomb-like), never a proportional damping. Speeds below `rest_speed`
  // snap to zero so the ball can come to a genuine rest.
  static resolve_ground_contact(
    ball: BallState,
    dt: number,
    ballRadius: number,
    restitution: number,
    groundFriction: number,
    restSpeed: number,
  ): void {
    if (ball.position.y > ballRadius) return;
    ball.position = new Vector3(ball.position.x, ballRadius, ball.position.z);
    BallPhysics.bounce(ball, Vector3.UP, restitution);
    if (Math.abs(ball.velocity.y) < restSpeed) {
      ball.velocity = new Vector3(ball.velocity.x, 0, ball.velocity.z);
    }
    const frictionDecel = maxf(0, groundFriction) * dt;
    const ground = new Vector2(ball.velocity.x, ball.velocity.z);
    const speed = ground.length();
    if (speed > 0) {
      const slowed = maxf(0, speed - frictionDecel);
      const direction = ground.div(speed);
      ball.velocity = new Vector3(direction.x * slowed, ball.velocity.y, direction.y * slowed);
    }
    if (ball.ground_speed() < restSpeed) {
      ball.velocity = new Vector3(0, ball.velocity.y, 0);
    }
  }

  // Clamp ball speed to a physical top speed to keep the sim bounded.
  static clamp_speed(ball: BallState, maxSpeed: number): void {
    if (ball.velocity.length() > maxSpeed) {
      ball.velocity = ball.velocity.normalized().mul(maxSpeed);
    }
  }
}

src/sim/ball_state.ts:
// BallState - ball entity owned by MatchSim (pure state, no rendering).
//
// Position/velocity are in metres and m/s on the sim's coordinate frame:
// X runs goal-to-goal (length), Z runs touchline-to-touchline (width), Y is
// height above the pitch. `angular_velocity` is the ball's spin in rad/s
// (right-hand rule around each axis) and drives the Magnus curve force
// computed by BallPhysics (task 1.1). The ball is never parented to a player.
import { Vector2, Vector3 } from "./vec.ts";

export class BallState {
  position = new Vector3();
  velocity = new Vector3();
  angular_velocity = new Vector3();

  reset(spawnHeight: number): void {
    this.position = new Vector3(0, spawnHeight, 0);
    this.velocity = new Vector3();
    this.angular_velocity = new Vector3();
  }

  // Horizontal (ground-plane) speed, ignoring height component.
  ground_speed(): number {
    return new Vector2(this.velocity.x, this.velocity.z).length();
  }

  has_finite_state(): boolean {
    return this.position.isFinite() && this.velocity.isFinite() && this.angular_velocity.isFinite();
  }

  to_dict(): Record<string, number> {
    return {
      px: this.position.x, py: this.position.y, pz: this.position.z,
      vx: this.velocity.x, vy: this.velocity.y, vz: this.velocity.z,
      wx: this.angular_velocity.x, wy: this.angular_velocity.y, wz: this.angular_velocity.z,
    };
  }
}

src/sim/cli.ts:
// Headless match runner (port of sim/cli.gd's run loop and the golden-replay
// harness's _run_match_log). Read-only core.
//
// Runs one seeded match and returns its JSON-Lines MatchLog: header, initial
// snapshot, every event (stamped with the tick count after the tick that
// produced it), a snapshot every `snapshotInterval` ticks, a final snapshot
// and the footer. Deterministic: the same seed and the same inputs must
// always reproduce a byte-identical log (the golden-replay criterion).
import { MatchSim, TICK_HZ } from "./match_sim.ts";
import { MatchLog } from "./match_log.ts";
import { AiProvider, InputProvider } from "./input_provider.ts";
import type { Tuning } from "./match_config.ts";

export const DEFAULT_TICKS = 600;
export const DEFAULT_SNAPSHOT_INTERVAL = 30;

export type RunOptions = {
  snapshotInterval?: number;
  tuning?: Tuning | null;
  // Factory so every run gets fresh providers; defaults to AI vs AI.
  providers?: (() => InputProvider[]) | null;
};

export function runMatchLog(seedValue: number, ticks: number = DEFAULT_TICKS, options: RunOptions = {}): MatchLog {
  const snapshotInterval = options.snapshotInterval ?? DEFAULT_SNAPSHOT_INTERVAL;
  const sim = new MatchSim(seedValue, options.tuning ?? null);
  const log = new MatchLog();
  const providers = options.providers ? options.providers() : [new AiProvider(0), new AiProvider(1)];
  const tickHz = sim.config.get_int("match", "tick_hz", TICK_HZ);
  log.header(seedValue, ticks, tickHz, sim.players);
  log.snapshot(sim);
  for (let i = 0; i < ticks; i += 1) {
    const events = sim.advance(providers);
    for (const e of events) log.event(sim.tick_count, String(e.event), e);
    if (snapshotInterval > 0 && sim.tick_count % snapshotInterval === 0) log.snapshot(sim);
  }
  log.snapshot(sim);
  log.footer(sim);
  return log;
}

src/sim/dribble.ts:
// Dribble - carrying the ball as repeated physics touches.
//
// architecture.md is explicit about the model: "The ball is never parented to
// a player. 'Dribbling' = repeated small touches by the locomotion system,
// each one a physics impulse." So there is no possession flag and no ball
// attachment anywhere in the sim - a dribbling player is simply one who keeps
// knocking a loose ball into the space ahead of them, and an opponent can take
// it at any moment because it is always a free physics object.
//
// Pure and stateless like the other sim models; all constants come from tuning
// JSON.
import { Vector2, Vector3, clampf, minf } from "./vec.ts";

// Tuning band for carrying the ball.
export class DribbleSettings {
  // How close the ball must be for a dribble touch to be available.
  reach = 1.3;
  // Ball speed after a touch, as a multiple of the player's speed.
  push_factor = 1.25;
  // Blend between the player's run direction (0) and where they are facing (1).
  lead_bias = 0.55;
  // Below this the player is not really moving, so the ball is left alone.
  min_player_speed = 0.6;
  // Above this *relative* speed the ball is getting away from the player.
  max_relative_speed = 9.0;
  // Ticks between touches. Longer means fewer, bigger knocks.
  touch_interval_ticks = 7;
}

export const Dribble = {
  // Is this player in a position to knock the ball on? `relativeSpeed` is the
  // ball's speed relative to the player, not its absolute speed.
  can_touch(
    settings: DribbleSettings, playerPosition: Vector2, playerSpeed: number, ballGround: Vector2,
    relativeSpeed: number,
  ): boolean {
    if (playerSpeed < settings.min_player_speed) return false;
    if (relativeSpeed > settings.max_relative_speed) return false;
    return playerPosition.distanceTo(ballGround) <= settings.reach;
  },

  // The ball velocity produced by one dribble touch: direction blends the run
  // with the body orientation; a dribble touch never lifts the ball.
  touch_velocity(settings: DribbleSettings, playerVelocity: Vector2, facing: Vector2, ballHeight: number): Vector3 {
    const run = playerVelocity.length() > 0.0001 ? playerVelocity.normalized() : Vector2.ZERO;
    const look = facing.length() > 0.0001 ? facing.normalized() : run;
    const weight = clampf(settings.lead_bias, 0.0, 1.0);
    let direction = run.add(look.sub(run).mul(weight)).normalized();
    if (direction.length() < 0.0001) direction = run;
    const speed = playerVelocity.length() * settings.push_factor;
    return new Vector3(direction.x * speed, minf(ballHeight, 0.0), direction.y * speed);
  },
};

src/sim/first_touch.ts:
// FirstTouch - how a player receives a moving ball (task 1.4, "the core mechanic").
//
// A continuous quality score decides how much incoming momentum the player
// kills and how far the ball squirts away when they get it wrong.
//
// Quality: three factors normalised to 0..1 and combined by tuning weights -
// orientation (facing into the oncoming ball), closing speed (standing still
// is easiest; sprinting costs an extra penalty) and ball speed.
//
// Outcome: quality selects `retention` (speed surviving the touch), shaped by
// the requested mode - CUSHION (default), KILL (multiplies retention down) or
// KNOCK_ON (push along the player's facing at a quality-scaled speed). A
// failed touch also deflects laterally by `errorBias * max_error * (1 - q)`;
// `errorBias` is supplied by the caller (MatchSim draws it from the seeded
// RNG) so this module stays pure.
import { Vector2, Vector3, clampf, lerpf, minf } from "./vec.ts";

export const TouchMode = { CUSHION: 0, KILL: 1, KNOCK_ON: 2 } as const;

export class FirstTouchSettings {
  trigger_speed = 1.0;
  retention_poor = 0.85;
  retention_good = 0.12;
  kill_multiplier = 0.25;
  knock_on_speed = 5.0;
  max_error = 4.0;
  reference_ball_speed = 18.0;
  weight_orientation = 0.5;
  weight_closing_speed = 0.3;
  weight_ball_speed = 0.2;
  sprint_penalty = 0.15;
  cooldown_ticks = 6;
}

export class FirstTouchResult {
  velocity: Vector3;
  angular_velocity: Vector3;
  quality: number;
  mode: number;

  constructor(velocity: Vector3, angularVelocity: Vector3, quality: number, mode: number) {
    this.velocity = velocity;
    this.angular_velocity = angularVelocity;
    this.quality = quality;
    this.mode = mode;
  }
}

export class FirstTouch {
  static quality_for(
    settings: FirstTouchSettings,
    facing: Vector2,
    velocity: Vector2,
    ballDirection: Vector2,
    ballSpeed: number,
    playerMaxSpeed: number,
    sprinting: boolean,
  ): number {
    let orientation = 0.5;
    if (facing.length() > 0.0001 && ballDirection.length() > 0.0001) {
      orientation = (facing.normalized().dot(ballDirection.normalized().neg()) + 1) * 0.5;
    }
    let speedNorm = 0;
    if (playerMaxSpeed > 0.0001) speedNorm = clampf(velocity.length() / playerMaxSpeed, 0, 1);
    let ballNorm = 0;
    if (settings.reference_ball_speed > 0.0001) {
      ballNorm = clampf(ballSpeed / settings.reference_ball_speed, 0, 1);
    }
    let score = settings.weight_orientation * orientation
      + settings.weight_closing_speed * (1 - speedNorm)
      + settings.weight_ball_speed * (1 - ballNorm);
    if (sprinting) score -= settings.sprint_penalty;
    return clampf(score, 0, 1);
  }

  static receive(
    settings: FirstTouchSettings,
    mode: number,
    quality: number,
    facing: Vector2,
    ballVelocity: Vector3,
    ballSpin: Vector3 = Vector3.ZERO,
    errorBias = 0,
  ): FirstTouchResult {
    const q = clampf(quality, 0, 1);
    const ground = new Vector2(ballVelocity.x, ballVelocity.z);
    const speed = ground.length();
    const direction = speed > 0.0001 ? ground.normalized() : Vector2.ZERO;

    let outgoing = Vector2.ZERO;
    if (mode === TouchMode.KNOCK_ON && facing.length() > 0.0001) {
      const push = settings.knock_on_speed * (0.4 + 0.6 * q);
      outgoing = facing.normalized().mul(push);
    } else {
      let retention = lerpf(settings.retention_poor, settings.retention_good, q);
      if (mode === TouchMode.KILL) retention *= settings.kill_multiplier;
      outgoing = direction.mul(speed * retention);
    }

    // Mis-control: perpendicular-and-add (no trig) keeps this exact everywhere.
    if (direction.length() > 0.0001) {
      const lateral = new Vector2(-direction.y, direction.x);
      outgoing = outgoing.add(lateral.mul(errorBias * settings.max_error * (1 - q)));
    }

    // Receiving flattens the ball and scrubs spin in proportion to quality.
    const vertical = minf(ballVelocity.y * (1 - q), ballVelocity.y);
    const spin = ballSpin.mul(1 - q);
    return new FirstTouchResult(new Vector3(outgoing.x, vertical, outgoing.y), spin, q, mode);
  }

  static mode_from_input(value: number): number {
    if (value === TouchMode.KILL) return TouchMode.KILL;
    if (value === TouchMode.KNOCK_ON) return TouchMode.KNOCK_ON;
    return TouchMode.CUSHION;
  }

  static mode_name(mode: number): string {
    if (mode === TouchMode.KILL) return "kill";
    if (mode === TouchMode.KNOCK_ON) return "knock_on";
    return "cushion";
  }
}

src/sim/input_provider.ts:
// InputProvider - the input abstraction feeding MatchSim.
//
// Every input source (local pads, network peers, AI bots, recorded replays)
// implements `collect(sim)` and returns a per-tick Map keyed by player id. The
// sim stays agnostic about where inputs come from - it receives one merged Map
// per tick. Each input entry is a PlayerInput (see the plan's input contract):
//   move: Vector2 (desired ground-plane direction, magnitude <= 1)
//   aim: Vector2 (desired facing; zero means "keep current facing")
//   sprint: boolean, kick: boolean
//   kick_type: number (KickType: 0 PASS, 1 SHOT, 2 LOB)
//   kick_power: number (0..1 button-hold charge)
//   touch_mode: number (TouchMode: 0 CUSHION, 1 KILL, 2 KNOCK_ON - applied
//     when receiving rather than striking)
import { KickType } from "./kick.ts";
import { TouchMode } from "./first_touch.ts";
import type { PlayerState } from "./player_state.ts";
import { Vector2, clampf, maxf } from "./vec.ts";

export type PlayerInput = {
  move: Vector2;
  aim: Vector2;
  sprint: boolean;
  kick: boolean;
  kick_type: number;
  kick_power: number;
  touch_mode: number;
};

export type InputMap = Map<number, PlayerInput>;

// Deep copy of one input entry (GDScript Dictionary.duplicate(true)).
export function clone_input(input: PlayerInput): PlayerInput {
  const copy = { ...input } as PlayerInput;
  if (input.move instanceof Vector2) copy.move = input.move.copy();
  if (input.aim instanceof Vector2) copy.aim = input.aim.copy();
  return copy;
}

export function clone_inputs(inputs: InputMap): InputMap {
  const out: InputMap = new Map();
  for (const [id, input] of inputs) out.set(id, clone_input(input));
  return out;
}

export class InputProvider {
  // Player ids this provider is responsible for. Empty means "all".
  player_ids: number[];

  constructor(ids: number[] = []) {
    this.player_ids = ids;
  }

  // Override: return a Map { player_id: input } for owned players.
  collect(_sim: any): InputMap {
    return new Map();
  }

  static make_input(
    move: Vector2,
    sprint = false,
    kick = false,
    aim: Vector2 = Vector2.ZERO,
    kickType: number = KickType.PASS,
    kickPower = 1.0,
    touchMode: number = TouchMode.CUSHION,
  ): PlayerInput {
    if (move.length() > 1) move = move.normalized();
    if (aim.length() > 1) aim = aim.normalized();
    return {
      move,
      aim,
      sprint,
      kick,
      kick_type: kickType,
      kick_power: clampf(kickPower, 0, 1),
      touch_mode: touchMode,
    };
  }

  static idle(): PlayerInput {
    return InputProvider.make_input(Vector2.ZERO, false, false);
  }
}

// AI bot: chases the ball with the nearest player, holds formation with the
// rest, and requests a kick toward the opponent goal when in control range.
// All randomness is drawn from the sim's seeded RNG so matches stay reproducible.
export class AiProvider extends InputProvider {
  team: number;

  constructor(teamId: number, ids: number[] = []) {
    super(ids);
    this.team = teamId;
  }

  collect(sim: any): InputMap {
    const out: InputMap = new Map();
    const owned = this.owned_players(sim);
    if (owned.length === 0) return out;
    const ballPos = new Vector2(sim.ball.position.x, sim.ball.position.z);
    const chaser = this.nearest_to_ball(owned, ballPos);
    const jitter = sim.config.get_float("ai", "chase_jitter", 0.1);
    const control = sim.control_radius() + sim.ball_radius();
    for (const p of owned) {
      if (p === chaser) {
        let dir = ballPos.sub(p.position);
        dir = dir.add(new Vector2(sim.rng.jitter(jitter), sim.rng.jitter(jitter)));
        const sprint = p.position.distanceTo(ballPos) > 4.0;
        const kick = p.position.distanceTo(ballPos) <= control;
        // The chaser aims at the target goal while steering toward the ball.
        const goal: Vector2 = sim.opponent_goal_center(this.team);
        const aim = goal.sub(p.position);
        // Shoot when the goal is in range, otherwise play a pass upfield.
        const goalDistance = p.position.distanceTo(goal);
        const shootRange = sim.config.get_float("ai", "shoot_range", 14.0);
        let kickType: number = KickType.PASS;
        let kickPower = 0.6;
        if (goalDistance <= shootRange) {
          kickType = KickType.SHOT;
          kickPower = clampf(goalDistance / maxf(shootRange, 0.001), 0.35, 1.0);
        }
        out.set(p.id, InputProvider.make_input(dir, sprint, kick, aim, kickType, kickPower));
      } else {
        // Off the ball: run to the formation anchor while watching the ball.
        out.set(p.id, InputProvider.make_input(p.home.sub(p.position), false, false, ballPos.sub(p.position)));
      }
    }
    return out;
  }

  owned_players(sim: any): PlayerState[] {
    return sim.players.filter((p: PlayerState) => p.team === this.team
      && (this.player_ids.length === 0 || this.player_ids.includes(p.id)));
  }

  nearest_to_ball(owned: PlayerState[], ballPos: Vector2): PlayerState {
    let best = owned[0];
    let bestD = best.position.distanceSquaredTo(ballPos);
    for (const p of owned) {
      const d = p.position.distanceSquaredTo(ballPos);
      if (d < bestD) {
        bestD = d;
        best = p;
      }
    }
    return best;
  }
}

// Scripted/local provider: replays a fixed input per player, or a per-tick
// table keyed by tick. Stands in for local gamepads and recorded-input replays.
export class ScriptedProvider extends InputProvider {
  script_inputs: InputMap = new Map();
  per_tick: Map<number, InputMap> = new Map();

  collect(sim: any): InputMap {
    const table = this.per_tick.get(sim.tick_count);
    return clone_inputs(table !== undefined ? table : this.script_inputs);
  }
}

// Network provider (Phase 3 stub): serves inputs pushed by remote peers for a
// given tick, defaulting to idle when a packet has not arrived yet.
export class NetworkProvider extends InputProvider {
  private buffer: Map<number, InputMap> = new Map();

  push(tick: number, inputs: InputMap): void {
    this.buffer.set(tick, inputs);
  }

  collect(sim: any): InputMap {
    const buffered = this.buffer.get(sim.tick_count);
    if (buffered !== undefined) return buffered;
    const out: InputMap = new Map();
    for (const pid of this.player_ids) out.set(pid, InputProvider.idle());
    return out;
  }
}

src/sim/kick.ts:
// Kick - pure impulse + spin model for striking the ball (task 1.3).
//
// Three mechanics, one model. Each produces a horizontal impulse, a vertical
// loft, and a spin vector; the differences are entirely in the tuning bands:
//   PASS - grounded and accurate; power interpolates speed between
//          pass.speed_min and pass.speed_max (the "weighted pass").
//   SHOT - power-hold strike: highest speed band, low loft, topspin (dips).
//   LOB  - lifted ball: highest loft, lowest speed, backspin (floats).
//
// Spin model (BallPhysics applies Magnus as magnus_coeff * (omega x v)):
// - Sidespin (omega along +Y) curves the ball left/right. It comes from the
//   approach angle: the signed lateral component of the striker's velocity
//   relative to the kick direction (2D cross product), scaled by
//   approach_spin_factor, plus a caller-supplied bias, clamped to max_side_spin.
// - Top/backspin (omega along up x travel) gives a purely vertical force:
//   axial_spin > 0 dips, < 0 floats.
//
// `build` itself performs no randomness: the caller supplies the seeded bias.
import { Vector2, Vector3, clampf, lerpf } from "./vec.ts";

export const KickType = { PASS: 0, SHOT: 1, LOB: 2 } as const;

const UP = new Vector3(0, 1, 0);

// Per-mechanic tuning band, built by MatchSim from tuning JSON.
export class KickProfile {
  speed_min: number;
  speed_max: number;
  loft_min: number;
  loft_max: number;
  // Spin about the across-travel axis: > 0 topspin (dips), < 0 backspin.
  axial_spin: number;

  constructor(speedMin: number, speedMax: number, loftMin: number, loftMax: number, axialSpin: number) {
    this.speed_min = speedMin;
    this.speed_max = speedMax;
    this.loft_min = loftMin;
    this.loft_max = loftMax;
    this.axial_spin = axialSpin;
  }
}

// Resulting impulse for one strike: a world-space ball velocity plus spin.
export class KickImpulse {
  velocity: Vector3;
  angular_velocity: Vector3;

  constructor(velocity: Vector3, angularVelocity: Vector3) {
    this.velocity = velocity;
    this.angular_velocity = angularVelocity;
  }
}

export class Kick {
  // `direction` is the aim (need not be normalised). `power` is the 0..1
  // charge. `strikerVelocity` is the player's ground-plane velocity.
  static build(
    profile: KickProfile,
    direction: Vector2,
    power: number,
    strikerVelocity: Vector2,
    approachSpinFactor: number,
    maxSideSpin: number,
    sideSpinBias = 0,
  ): KickImpulse {
    const charge = clampf(power, 0, 1);
    const dir = direction.normalized();
    const speed = lerpf(profile.speed_min, profile.speed_max, charge);
    const loft = lerpf(profile.loft_min, profile.loft_max, charge);

    const lateral = dir.cross(strikerVelocity);
    const sideSpin = clampf(lateral * approachSpinFactor + sideSpinBias, -maxSideSpin, maxSideSpin);

    const travel = new Vector3(dir.x, 0, dir.y);
    const spin = UP.mul(sideSpin).add(UP.cross(travel).mul(profile.axial_spin));
    return new KickImpulse(new Vector3(dir.x * speed, loft, dir.y * speed), spin);
  }

  // Map an input's requested kick type onto KickType, defaulting to PASS.
  static type_from_input(value: number): number {
    if (value === KickType.SHOT) return KickType.SHOT;
    if (value === KickType.LOB) return KickType.LOB;
    return KickType.PASS;
  }

  // Human-readable name for match-log events.
  static type_name(kickType: number): string {
    if (kickType === KickType.SHOT) return "shot";
    if (kickType === KickType.LOB) return "lob";
    return "pass";
  }
}

src/sim/locomotion.ts:
// Locomotion - pure player movement, stamina, and decoupled-aim integrator (task 1.2).
//
// Stateless transforms of a PlayerState plus caller-supplied constants (all
// sourced from tuning JSON by MatchSim), stepped at the fixed tick.
//
// Two independent layers per tick, matching the two analog sticks:
//   - Movement: `moveInput` (magnitude <= 1) scales speed continuously;
//     `sprintRequested` raises the top speed by `sprintMultiplier` but only
//     while `stamina` is above `staminaSprintMin`. Sprinting drains stamina
//     (points per second); otherwise it recovers, capped at `staminaMax`.
//   - Aim: `aimInput` drives `facing`, turning toward the aim direction at a
//     bounded `turnRate` (rad/s), decoupled from velocity. A zero aim input
//     leaves `facing` unchanged.
import { PlayerState } from "./player_state.ts";
import { Vector2, clampf, maxf, minf, wrapf } from "./vec.ts";

export class Locomotion {
  static update(
    player: PlayerState,
    moveInput: Vector2,
    aimInput: Vector2,
    sprintRequested: boolean,
    dt: number,
    maxSpeed: number,
    sprintMultiplier: number,
    acceleration: number,
    turnRate: number,
    staminaMax: number,
    staminaDrainRate: number,
    staminaRecoveryRate: number,
    staminaSprintMin: number,
  ): void {
    Locomotion.update_movement(
      player, moveInput, sprintRequested, dt,
      maxSpeed, sprintMultiplier, acceleration,
      staminaMax, staminaDrainRate, staminaRecoveryRate, staminaSprintMin,
    );
    Locomotion.update_aim(player, aimInput, turnRate, dt);
  }

  static update_movement(
    player: PlayerState,
    moveInput: Vector2,
    sprintRequested: boolean,
    dt: number,
    maxSpeed: number,
    sprintMultiplier: number,
    acceleration: number,
    staminaMax: number,
    staminaDrainRate: number,
    staminaRecoveryRate: number,
    staminaSprintMin: number,
  ): void {
    const moveMagnitude = clampf(moveInput.length(), 0, 1);
    let moveDirection = Vector2.ZERO;
    if (moveInput.length() > 0.0001) moveDirection = moveInput.normalized();

    const canSprint = sprintRequested && player.stamina > staminaSprintMin;
    const topSpeed = maxSpeed * (canSprint ? sprintMultiplier : 1);
    // Analog speed: the stick's own magnitude scales the target speed.
    const desiredVelocity = moveDirection.mul(moveMagnitude * topSpeed);

    player.velocity = player.velocity.moveToward(desiredVelocity, acceleration * dt);
    player.position = player.position.add(player.velocity.mul(dt));

    player.sprinting = canSprint && moveMagnitude > 0.01;
    if (player.sprinting) {
      player.stamina = maxf(0, player.stamina - staminaDrainRate * dt);
    } else {
      player.stamina = minf(staminaMax, player.stamina + staminaRecoveryRate * dt);
    }
  }

  static update_aim(player: PlayerState, aimInput: Vector2, turnRate: number, dt: number): void {
    if (aimInput.length() <= 0.0001) {
      // Decoupled aim: no stick input means "keep looking where I was".
      return;
    }
    const targetDirection = aimInput.normalized();
    const currentAngle = player.facing.angle();
    const targetAngle = targetDirection.angle();
    const deltaAngle = wrapf(targetAngle - currentAngle, -Math.PI, Math.PI);
    const maxStep = turnRate * dt;
    const step = clampf(deltaAngle, -maxStep, maxStep);
    player.facing = player.facing.rotated(step).normalized();
  }
}

src/sim/match_config.ts:
// MatchConfig - loads gameplay constants from the tuning JSON (read-only core).
//
// Per spec ("All gameplay constants live in tuning JSON, never hardcoded"),
// MatchSim reads every numeric knob from here. Nested sections are exposed as
// plain objects; MatchSim pulls typed values with defaults so a partial tuning
// object still runs.
import { readFileSync } from "node:fs";

export const DEFAULT_TUNING_URL = new URL("../../data/tuning.json", import.meta.url);

export type Tuning = Record<string, unknown>;

export class MatchConfig {
  data: Tuning;

  // `source` is a tuning object, or null to load data/tuning.json.
  constructor(source: Tuning | null = null) {
    this.data = source !== null && typeof source === "object"
      ? source
      : JSON.parse(readFileSync(DEFAULT_TUNING_URL, "utf8"));
  }

  // Read a value at section/key, falling back to `fallback` if absent.
  get_value(section: string, key: string, fallback: unknown): unknown {
    const block = this.data[section];
    if (block !== null && typeof block === "object" && !Array.isArray(block)
      && Object.prototype.hasOwnProperty.call(block, key)) {
      return (block as Record<string, unknown>)[key];
    }
    return fallback;
  }

  get_float(section: string, key: string, fallback: number): number {
    return Number(this.get_value(section, key, fallback));
  }

  // GDScript int() truncates toward zero.
  get_int(section: string, key: string, fallback: number): number {
    return Math.trunc(Number(this.get_value(section, key, fallback)));
  }
}

src/sim/match_log.ts:
// MatchLog - replay / match-log recorder for MatchSim.
//
// Emits the match as JSON Lines: a header describing the seeded run, event and
// snapshot records during play, and a summary footer. This is the seam the
// golden-replay determinism check reads from. Records are plain objects and
// are only serialised on output.
export class MatchLog {
  records: Record<string, unknown>[] = [];

  record(entry: Record<string, unknown>): void {
    this.records.push(entry);
  }

  header(seed: number, ticks: number, tickHz: number, players: any[]): void {
    const roster = players.map((p) => ({ id: p.id, team: p.team, role: p.role }));
    this.record({ type: "header", seed, ticks, tick_hz: tickHz, players: roster });
  }

  snapshot(sim: any): void {
    this.record({
      type: "snapshot",
      tick: sim.tick_count,
      ball: sim.ball.to_dict(),
      players: sim.players.map((p: any) => p.to_dict()),
      score: { ...sim.score },
    });
  }

  event(tick: number, name: string, data: Record<string, unknown> = {}): void {
    const entry: Record<string, unknown> = { type: "event", tick, event: name };
    for (const key of Object.keys(data)) entry[key] = data[key];
    this.record(entry);
  }

  footer(sim: any): void {
    this.record({
      type: "footer",
      final_tick: sim.tick_count,
      score: { ...sim.score },
      possession_ticks: { ...sim.possession_ticks },
      state_digest: sim.state_digest(),
    });
  }

  // Serialise every record to newline-delimited JSON.
  to_jsonl(): string {
    return this.records.map((entry) => JSON.stringify(entry)).join("\n");
  }
}

src/sim/match_sim.ts:
// MatchSim - deterministic, headless-runnable simulation core.
//
// MatchSim owns all gameplay state (players, ball, score) and is advanced by
// fixed-tick calls to `tick()`. It is PURE and DETERMINISTIC: no rendering, no
// reads of presentation state, and no unseeded randomness (all random draws go
// through the seeded `SimRng`).
//
// Coordinate frame: X runs goal-to-goal (length), Z runs touchline-to-touchline
// (width); players live on that ground plane (Vector2 x = X, y = Z), the ball
// adds height Y. Team 0 attacks +X, team 1 attacks -X. Every numeric constant is
// read from the tuning JSON via MatchConfig.
//
// The scaffold establishes the fixed-tick loop, entity state and input plumbing.
// Ball aerodynamics (task 1.1, BallPhysics), player locomotion (task 1.2,
// Locomotion), kick mechanics (task 1.3, Kick) and first touch (task 1.4,
// FirstTouch) plug into it.
import { BallPhysics } from "./ball_physics.ts";
import { BallState } from "./ball_state.ts";
import { Dribble, DribbleSettings } from "./dribble.ts";
import { FirstTouch, FirstTouchSettings, TouchMode } from "./first_touch.ts";
import type { InputMap, InputProvider, PlayerInput } from "./input_provider.ts";
import { Kick, KickProfile, KickType } from "./kick.ts";
import { Locomotion } from "./locomotion.ts";
import { MatchConfig, type Tuning } from "./match_config.ts";
import { PlayerState } from "./player_state.ts";
import { SimRng } from "./sim_rng.ts";
import { SportRules } from "./sport_rules.ts";
import { SoccerRules } from "./sports/soccer_rules.ts";
import { Vector2, Vector3, clampf, maxi, snappedf } from "./vec.ts";

export const TICK_HZ = 60;
export const TICK_DELTA = 1.0 / TICK_HZ;

export type SimEvent = Record<string, unknown> & { event: string };

export class MatchSim {
  config: MatchConfig;
  // The sport supplying scoring, restarts and field rules. Defaults to soccer;
  // see multi-sport-core.md for why this is a seam rather than baked in.
  rules: SportRules;
  rng: SimRng;
  ball: BallState;
  players: PlayerState[] = [];
  score: Record<number, number> = { 0: 0, 1: 0 };
  possession_ticks: Record<number, number> = { 0: 0, 1: 0 };
  tick_count = 0;
  last_toucher_team = -1;

  // Cached tuning (pulled once so the hot loop avoids lookups).
  private _tick_delta = TICK_DELTA;
  private _team_size = 3;
  private _half_length = 20;
  private _half_width = 12.5;
  private _ball_radius = 0.11;
  private _gravity = 9.81;
  private _linear_drag = 0.15;
  private _magnus_coefficient = 0.12;
  private _spin_drag = 0.6;
  private _ground_restitution = 0.55;
  private _ground_friction = 2.5;
  private _rest_speed = 0.05;
  private _ball_max_speed = 45;
  private _player_radius = 0.4;
  private _player_max_speed = 7;
  private _sprint_multiplier = 1.35;
  private _acceleration = 30;
  private _turn_rate = 12;
  private _stamina_max = 100;
  private _stamina_drain_rate = 25;
  private _stamina_recovery_rate = 15;
  private _stamina_sprint_min = 5;
  private _control_radius = 1;
  private _reach_height = 1.6;
  private _touch_cooldown = 8;
  private _formation_depth = 8;
  private _formation_spread = 6;
  private _kick_profiles: Map<number, KickProfile> = new Map();
  private _approach_spin_factor = 1.2;
  private _max_side_spin = 14;
  private _side_spin_jitter = 0.6;
  private _first_touch: FirstTouchSettings = new FirstTouchSettings();
  private _first_touch_error_jitter = 1.0;
  private _dribble: DribbleSettings = new DribbleSettings();

  constructor(seedValue = 0, configSource: MatchConfig | Tuning | null = null, sport: SportRules | null = null) {
    this.config = configSource instanceof MatchConfig ? configSource : new MatchConfig(configSource);
    this.rules = sport !== null ? sport : new SoccerRules();
    this.rng = new SimRng(seedValue);
    this._cache_tuning();
    this.ball = new BallState();
    this._spawn_players();
    this.kickoff();
  }

  private _cache_tuning(): void {
    const c = this.config;
    this._tick_delta = 1.0 / c.get_int("match", "tick_hz", TICK_HZ);
    this._team_size = c.get_int("match", "team_size", 3);
    this._half_length = c.get_float("pitch", "length", 40.0) * 0.5;
    this._half_width = c.get_float("pitch", "width", 25.0) * 0.5;
    this._ball_radius = c.get_float("ball", "radius", 0.11);
    this._gravity = c.get_float("ball", "gravity", 9.81);
    this._linear_drag = c.get_float("ball", "linear_drag", 0.15);
    this._magnus_coefficient = c.get_float("ball", "magnus_coefficient", 0.12);
    this._spin_drag = c.get_float("ball", "spin_drag", 0.6);
    this._ground_restitution = c.get_float("ball", "ground_restitution", 0.55);
    this._ground_friction = c.get_float("ball", "ground_friction", 2.5);
    this._rest_speed = c.get_float("ball", "rest_speed", 0.05);
    this._ball_max_speed = c.get_float("ball", "max_speed", 45.0);
    this._player_radius = c.get_float("player", "radius", 0.4);
    this._player_max_speed = c.get_float("player", "max_speed", 7.0);
    this._sprint_multiplier = c.get_float("player", "sprint_multiplier", 1.35);
    this._acceleration = c.get_float("player", "acceleration", 30.0);
    this._turn_rate = c.get_float("player", "turn_rate_rad", 12.0);
    this._stamina_max = c.get_float("player", "stamina_max", 100.0);
    this._stamina_drain_rate = c.get_float("player", "stamina_drain_rate", 25.0);
    this._stamina_recovery_rate = c.get_float("player", "stamina_recovery_rate", 15.0);
    this._stamina_sprint_min = c.get_float("player", "stamina_sprint_min", 5.0);
    this._control_radius = c.get_float("player", "control_radius", 1.0);
    this._reach_height = c.get_float("player", "reach_height", 1.6);
    this._touch_cooldown = c.get_int("player", "touch_cooldown_ticks", 8);
    this._formation_depth = c.get_float("ai", "formation_depth", 8.0);
    this._formation_spread = c.get_float("ai", "formation_spread", 6.0);
    this._cache_kick_tuning();
    if (this.rules !== undefined && this.rules !== null) this.rules.configure(c);
  }

  private _cache_kick_tuning(): void {
    this._kick_profiles = new Map([
      [KickType.PASS, this._kick_profile("pass", 6.0, 16.0, 0.0, 0.6, 2.0)],
      [KickType.SHOT, this._kick_profile("shot", 14.0, 30.0, 0.8, 3.2, 6.0)],
      [KickType.LOB, this._kick_profile("lob", 5.0, 13.0, 4.0, 8.0, -4.0)],
    ]);
    this._approach_spin_factor = this.config.get_float("kick", "approach_spin_factor", 1.2);
    this._max_side_spin = this.config.get_float("kick", "max_side_spin", 14.0);
    this._side_spin_jitter = this.config.get_float("kick", "side_spin_jitter", 0.6);
    this._cache_first_touch_tuning();
  }

  private _cache_first_touch_tuning(): void {
    const c = this.config;
    const s = new FirstTouchSettings();
    s.trigger_speed = c.get_float("first_touch", "trigger_speed", s.trigger_speed);
    s.retention_poor = c.get_float("first_touch", "retention_poor", s.retention_poor);
    s.retention_good = c.get_float("first_touch", "retention_good", s.retention_good);
    s.kill_multiplier = c.get_float("first_touch", "kill_multiplier", s.kill_multiplier);
    s.knock_on_speed = c.get_float("first_touch", "knock_on_speed", s.knock_on_speed);
    s.max_error = c.get_float("first_touch", "max_error", s.max_error);
    s.reference_ball_speed = c.get_float("first_touch", "reference_ball_speed", s.reference_ball_speed);
    s.weight_orientation = c.get_float("first_touch", "weight_orientation", s.weight_orientation);
    s.weight_closing_speed = c.get_float("first_touch", "weight_closing_speed", s.weight_closing_speed);
    s.weight_ball_speed = c.get_float("first_touch", "weight_ball_speed", s.weight_ball_speed);
    s.sprint_penalty = c.get_float("first_touch", "sprint_penalty", s.sprint_penalty);
    s.cooldown_ticks = c.get_int("first_touch", "cooldown_ticks", s.cooldown_ticks);
    this._first_touch = s;
    this._first_touch_error_jitter = c.get_float("first_touch", "error_jitter", 1.0);
    this._cache_dribble_tuning();
  }

  private _cache_dribble_tuning(): void {
    const c = this.config;
    const d = new DribbleSettings();
    d.reach = c.get_float("dribble", "reach", d.reach);
    d.push_factor = c.get_float("dribble", "push_factor", d.push_factor);
    d.lead_bias = c.get_float("dribble", "lead_bias", d.lead_bias);
    d.min_player_speed = c.get_float("dribble", "min_player_speed", d.min_player_speed);
    d.max_relative_speed = c.get_float("dribble", "max_relative_speed", d.max_relative_speed);
    d.touch_interval_ticks = c.get_int("dribble", "touch_interval_ticks", d.touch_interval_ticks);
    this._dribble = d;
  }

  // One mechanic's tuning band: the `kick` section nests an object per
  // mechanic; fall back per key for partial tuning.
  private _kick_profile(
    name: string, speedMin: number, speedMax: number, loftMin: number, loftMax: number, axialSpin: number,
  ): KickProfile {
    const raw = this.config.get_value("kick", name, {});
    const band = (raw !== null && typeof raw === "object" ? raw : {}) as Record<string, unknown>;
    const pick = (key: string, fallback: number) => Number(key in band ? band[key] : fallback);
    return new KickProfile(
      pick("speed_min", speedMin), pick("speed_max", speedMax),
      pick("loft_min", loftMin), pick("loft_max", loftMax), pick("axial_spin", axialSpin),
    );
  }

  // Re-read cached tuning after the config data has been edited in place (the
  // playable build's live-tuning overlay). Only re-reads data: a running match
  // keeps its positions, score and RNG stream.
  reload_tuning(): void {
    this._cache_tuning();
  }

  private _spawn_players(): void {
    this.players = [];
    let nextId = 0;
    for (const team of [0, 1]) {
      const dir = team === 0 ? 1.0 : -1.0;
      for (let role = 0; role < this._team_size; role += 1) {
        const p = new PlayerState();
        p.id = nextId;
        p.team = team;
        p.role = role;
        // Fan players across their defensive half; role 0 sits deepest.
        const lane = this._team_size <= 1 ? 0.0 : (role / (this._team_size - 1) - 0.5) * 2.0;
        const depth = -dir * this._formation_depth * (1.0 - role / maxi(this._team_size, 1));
        p.home = new Vector2(depth, lane * this._formation_spread);
        p.facing = new Vector2(dir, 0.0);
        p.stamina = this._stamina_max;
        this.players.push(p);
        nextId += 1;
      }
    }
  }

  // Restart play. Delegates to the sport's rules (soccer: kickoff at the centre
  // spot). Kept as a method on the sim because callers and tests treat "restart
  // the match" as a sim-level operation.
  kickoff(kickTeam = -1): void {
    this.rules.restart(this, kickTeam);
  }

  // --- Read-only helpers used by input providers ---------------------------

  opponent_goal_center(team: number): Vector2 {
    return new Vector2(team === 0 ? this._half_length : -this._half_length, 0.0);
  }

  control_radius(): number {
    return this._control_radius;
  }

  ball_radius(): number {
    return this._ball_radius;
  }

  // Merge inputs from every provider into one per-tick Map (later providers win).
  gather_inputs(providers: InputProvider[]): InputMap {
    const merged: InputMap = new Map();
    for (const provider of providers) {
      for (const [pid, input] of provider.collect(this)) merged.set(pid, input);
    }
    return merged;
  }

  // Convenience: gather inputs from providers then advance one tick.
  advance(providers: InputProvider[], delta = -1.0): SimEvent[] {
    return this.tick(this.gather_inputs(providers), delta);
  }

  // Advance the simulation exactly one fixed tick. Pure: same (state, inputs)
  // in -> same state out. Returns the discrete events that fired this tick.
  tick(inputs: InputMap, delta = -1.0): SimEvent[] {
    const dt = delta <= 0.0 ? this._tick_delta : delta;
    const events: SimEvent[] = [];
    this._update_players(inputs, dt);
    this._resolve_touches(inputs, events);
    this._integrate_ball(dt);
    this._resolve_bounds(events);
    this._track_possession();
    this.tick_count += 1;
    return events;
  }

  private _update_players(inputs: InputMap, dt: number): void {
    for (const p of this.players) {
      if (p.touch_cooldown > 0) p.touch_cooldown -= 1;
      let move = Vector2.ZERO;
      let aim = Vector2.ZERO;
      let sprint = false;
      const cmd = inputs.get(p.id);
      if (cmd !== undefined) {
        move = cmd.move ?? Vector2.ZERO;
        aim = cmd.aim ?? Vector2.ZERO;
        sprint = Boolean(cmd.sprint ?? false);
      }
      Locomotion.update(
        p, move, aim, sprint, dt,
        this._player_max_speed, this._sprint_multiplier, this._acceleration, this._turn_rate,
        this._stamina_max, this._stamina_drain_rate, this._stamina_recovery_rate, this._stamina_sprint_min,
      );
      this._clamp_to_pitch(p);
    }
  }

  private _clamp_to_pitch(p: PlayerState): void {
    const lx = this._half_length - this._player_radius;
    const lz = this._half_width - this._player_radius;
    p.position = new Vector2(clampf(p.position.x, -lx, lx), clampf(p.position.y, -lz, lz));
  }

  private _resolve_touches(inputs: InputMap, events: SimEvent[]): void {
    // The player closest to the ball wins the touch; ties break by id so the
    // result stays deterministic, but distance decides first.
    if (this.ball.position.y > this._reach_height) return;
    const ballGround = new Vector2(this.ball.position.x, this.ball.position.z);
    const reach = this._control_radius + this._ball_radius + this._player_radius;
    let winner: PlayerState | null = null;
    let winnerDistance = Infinity;
    for (const p of this.players) {
      if (p.touch_cooldown > 0) continue;
      if (!inputs.has(p.id)) continue;
      const distance = p.position.distanceTo(ballGround);
      if (distance > reach) continue;
      if (distance < winnerDistance) {
        winner = p;
        winnerDistance = distance;
      }
    }
    if (winner === null) return;
    const cmd = inputs.get(winner.id) as PlayerInput;
    if (Boolean(cmd.kick ?? false)) {
      this._kick_ball(winner, cmd, events);
      this._commit_challengers(winner, ballGround, reach);
    } else {
      this._receive_ball(winner, cmd, events);
    }
  }

  // Receive a moving ball (task 1.4). A player in the ball's path who is not
  // striking it still meets it, through the FirstTouch model. A ball already
  // trickling below `trigger_speed` needs no touch simulating.
  private _receive_ball(p: PlayerState, cmd: PlayerInput, events: SimEvent[]): void {
    const ground = new Vector2(this.ball.velocity.x, this.ball.velocity.z);
    const speed = ground.length();
    // How fast is the ball moving *relative to the player*? A ball running just
    // ahead of a sprinter, or a still ball they are running onto, are both
    // dribbling situations; only a ball genuinely flying past them is a
    // reception. Dribbling gets first refusal.
    const relativeSpeed = ground.sub(p.velocity).length();
    if (Dribble.can_touch(this._dribble, p.position, p.velocity.length(), this._ball_ground(), relativeSpeed)) {
      this._dribble_ball(p, events);
      return;
    }
    if (speed < this._first_touch.trigger_speed) return;
    const mode = FirstTouch.mode_from_input(Math.trunc(Number(cmd.touch_mode ?? TouchMode.CUSHION)));
    const quality = FirstTouch.quality_for(
      this._first_touch, p.facing, p.velocity, ground.normalized(), speed,
      this._player_max_speed, p.sprinting,
    );
    const result = FirstTouch.receive(
      this._first_touch, mode, quality, p.facing, this.ball.velocity, this.ball.angular_velocity,
      this.rng.jitter(this._first_touch_error_jitter),
    );
    this.ball.velocity = result.velocity;
    this.ball.angular_velocity = result.angular_velocity;
    p.touch_cooldown = this._first_touch.cooldown_ticks;
    this.last_toucher_team = p.team;
    events.push({
      event: "touch",
      player: p.id,
      team: p.team,
      touch: FirstTouch.mode_name(mode),
      quality: snappedf(quality, 0.001),
    });
  }

  // A challenge commits every player already contesting the ball (they lunged
  // and were beaten), so the kick can't be instantly returned.
  private _commit_challengers(kicker: PlayerState, ballGround: Vector2, reach: number): void {
    for (const p of this.players) {
      if (p === kicker) continue;
      if (p.position.distanceTo(ballGround) <= reach) {
        p.touch_cooldown = maxi(p.touch_cooldown, this._touch_cooldown);
      }
    }
  }

  // Strike the ball with whichever mechanic the input requested (task 1.3).
  // Aim comes from the input when supplied, otherwise from the player's
  // facing, otherwise toward the opponent goal. The seeded side-spin jitter is
  // drawn here so Kick.build stays pure.
  private _kick_ball(p: PlayerState, cmd: PlayerInput, events: SimEvent[]): void {
    const kickType = Kick.type_from_input(Math.trunc(Number(cmd.kick_type ?? KickType.PASS)));
    const power = clampf(Number(cmd.kick_power ?? 1.0), 0.0, 1.0);
    let aim: Vector2 = cmd.aim ?? Vector2.ZERO;
    if (aim.length() < 0.0001) aim = p.facing;
    if (aim.length() < 0.0001) aim = this.opponent_goal_center(p.team).sub(p.position);
    const profile = this._kick_profiles.get(kickType) as KickProfile;
    const impulse = Kick.build(
      profile, aim, power, p.velocity,
      this._approach_spin_factor, this._max_side_spin,
      this.rng.jitter(this._side_spin_jitter),
    );
    this.ball.velocity = impulse.velocity;
    this.ball.angular_velocity = impulse.angular_velocity;
    p.touch_cooldown = this._touch_cooldown;
    this.last_toucher_team = p.team;
    events.push({ event: "kick", player: p.id, team: p.team, kick: Kick.type_name(kickType), power });
  }

  // Knock a loose ball into the space ahead (dribbling, architecture.md). Not
  // possession: the ball stays a free physics object between touches, so an
  // opponent standing in the way can take it.
  private _dribble_ball(p: PlayerState, events: SimEvent[]): void {
    this.ball.velocity = Dribble.touch_velocity(this._dribble, p.velocity, p.facing, this.ball.velocity.y);
    this.ball.angular_velocity = Vector3.ZERO;
    p.touch_cooldown = this._dribble.touch_interval_ticks;
    this.last_toucher_team = p.team;
    events.push({ event: "dribble", player: p.id, team: p.team });
  }

  private _ball_ground(): Vector2 {
    return new Vector2(this.ball.position.x, this.ball.position.z);
  }

  private _integrate_ball(dt: number): void {
    BallPhysics.apply_forces(this.ball, dt, this._gravity, this._linear_drag, this._magnus_coefficient, this._spin_drag);
    BallPhysics.resolve_ground_contact(
      this.ball, dt, this._ball_radius, this._ground_restitution, this._ground_friction, this._rest_speed,
    );
    BallPhysics.clamp_speed(this.ball, this._ball_max_speed);
  }

  private _resolve_bounds(events: SimEvent[]): void {
    this.rules.resolve_bounds(this, events);
  }

  private _track_possession(): void {
    if (this.last_toucher_team >= 0) this.possession_ticks[this.last_toucher_team] += 1;
  }

  // Deterministic digest of the full sim state. Two runs with the same seed and
  // inputs must produce identical digests - the basis of the golden-replay check.
  state_digest(): number {
    const parts: string[] = [];
    parts.push(`t=${this.tick_count}`);
    parts.push(`s=${this.score[0]}:${this.score[1]}`);
    parts.push(MatchSim._quantize_vec3(this.ball.position));
    parts.push(MatchSim._quantize_vec3(this.ball.velocity));
    parts.push(MatchSim._quantize_vec3(this.ball.angular_velocity));
    for (const p of this.players) {
      parts.push(`${p.id}|${MatchSim._quantize_vec2(p.position)}|${MatchSim._quantize_vec2(p.velocity)}|`
        + `${MatchSim._quantize_vec2(p.facing)}|${p.stamina.toFixed(4)}`);
    }
    return MatchSim._hash(parts.join("\n"));
  }

  // Godot String.hash(): djb2 over the string's code points, as uint32.
  private static _hash(text: string): number {
    let hash = 5381;
    for (const ch of text) hash = (Math.imul(hash, 33) + (ch.codePointAt(0) as number)) >>> 0;
    return hash;
  }

  private static _quantize_vec3(v: Vector3): string {
    return `${v.x.toFixed(4)},${v.y.toFixed(4)},${v.z.toFixed(4)}`;
  }

  private static _quantize_vec2(v: Vector2): string {
    return `${v.x.toFixed(4)},${v.y.toFixed(4)}`;
  }

  // Invariant check: all entity state is finite (no NaN/inf).
  state_is_finite(): boolean {
    if (!this.ball.has_finite_state()) return false;
    return this.players.every((p) => p.has_finite_state());
  }
}

src/sim/player_state.ts:
// PlayerState - a footballer entity owned by MatchSim (pure state).
//
// Players live on the ground plane (X = length, Z = width); `position` and
// `velocity` are Vector2 in that plane (vector .y is the world Z axis). `home`
// is the AI formation anchor. `facing` is the player's aim / body-orientation
// unit vector, driven independently of `velocity` (task 1.2's decoupled aim).
// `stamina` fuels sprinting and is owned by Locomotion: it is measured in
// stamina points on the same scale as the tuning's player.stamina_max.
import { Vector2 } from "./vec.ts";

export class PlayerState {
  id = 0;
  team = 0;
  role = 0;
  position = new Vector2();
  velocity = new Vector2();
  home = new Vector2();
  facing = Vector2.RIGHT;
  stamina = 1.0;
  sprinting = false;
  touch_cooldown = 0;

  has_finite_state(): boolean {
    return this.position.isFinite() && this.velocity.isFinite() && this.facing.isFinite()
      && Number.isFinite(this.stamina);
  }

  to_dict(): Record<string, number | boolean> {
    return {
      id: this.id, team: this.team, role: this.role,
      px: this.position.x, pz: this.position.y,
      vx: this.velocity.x, vz: this.velocity.y,
      fx: this.facing.x, fz: this.facing.y,
      stamina: this.stamina, sprinting: this.sprinting,
    };
  }
}

src/sim/sim_rng.ts:
// SimRng - deterministic seeded random-number wrapper for MatchSim (read-only core).
//
// MatchSim must never draw from an unseeded source such as Math.random() (the
// GDScript original forbids the engine's global randf()/randi() for the same
// reason): all simulation randomness flows through one SimRng instance seeded
// from the match seed, so a given seed always reproduces an identical match.
//
// The stream is PCG32 (XSH-RR) with Godot's default increment, the generator
// behind Godot's RandomNumberGenerator.

const MASK64 = (1n << 64n) - 1n;
const MULTIPLIER = 6364136223846793005n;
const DEFAULT_INC = 1442695040888963407n;

export class SimRng {
  private state = 0n;
  private inc = 0n;
  private seedValue = 0;

  constructor(seedValue = 0) {
    this.reseed(seedValue);
  }

  // Reseed the stream. Resets the internal state so the sequence is reproducible.
  reseed(seedValue: number): void {
    this.seedValue = seedValue;
    this.state = 0n;
    this.inc = ((DEFAULT_INC << 1n) | 1n) & MASK64;
    this.next();
    this.state = (this.state + (BigInt.asUintN(64, BigInt(Math.trunc(seedValue))))) & MASK64;
    this.next();
  }

  // The seed this stream was initialised with (recorded in the match log header).
  get_seed(): number {
    return this.seedValue;
  }

  private next(): number {
    const old = this.state;
    this.state = (old * MULTIPLIER + this.inc) & MASK64;
    const xorshifted = Number((((old >> 18n) ^ old) >> 27n) & 0xffffffffn);
    const rot = Number(old >> 59n);
    return ((xorshifted >>> rot) | (xorshifted << ((-rot) & 31))) >>> 0;
  }

  // Uniform float in [0, 1).
  randf(): number {
    return this.next() / 4294967296;
  }

  // Uniform float in [from, to].
  randf_range(from: number, to: number): number {
    return this.randf() * (to - from) + from;
  }

  // Uniform integer in [from, to] inclusive.
  randi_range(from: number, to: number): number {
    return from + Math.floor(this.randf() * (to - from + 1));
  }

  // Signed float in [-magnitude, magnitude]; convenience for symmetric jitter.
  jitter(magnitude: number): number {
    return this.randf_range(-magnitude, magnitude);
  }
}

src/sim/sport_rules.ts:
// SportRules - the contract a sport supplies to MatchSim.
//
// MatchSim owns what every sport shares: a deterministic fixed-tick loop,
// entities, locomotion, ball physics and input plumbing. It should not know
// what a goal is, how a match restarts, or how points are awarded - those are
// sport rules, and they are the pieces that differ most between soccer,
// American football and basketball (multi-sport-core.md, stage 1).
//
// Implementations must preserve the sim's binding invariants: no unseeded
// randomness (draw from `sim.rng`), no engine or rendering calls.
import type { MatchConfig } from "./match_config.ts";
import type { MatchSim, SimEvent } from "./match_sim.ts";

export class SportRules {
  // Cache whatever geometry and constants the rules need from tuning data.
  // Called by MatchSim whenever tuning is (re)loaded, so live edits apply.
  configure(_config: MatchConfig): void {}

  // Resolve the ball leaving the field of play: scoring, rebounds, restarts.
  // Called once per tick after the ball has been integrated.
  resolve_bounds(_sim: MatchSim, _events: SimEvent[]): void {}

  // Put the match into its starting state (kickoff, snap, tip-off). `team` is
  // the side restarting; -1 means "keep the current one".
  restart(_sim: MatchSim, _team: number): void {}
}

src/sim/sports/soccer_rules.ts:
// SoccerRules - association football rules for MatchSim.
//
// Cage/street rules per spec.md's non-goals: no fouls, offside or cards. The
// ball rebounds off the touchlines rather than going out, and a goal restarts
// play at the centre spot. Everything here used to live inside MatchSim
// (multi-sport-core.md stage 1); the behaviour is unchanged.
import { BallPhysics } from "../ball_physics.ts";
import type { MatchConfig } from "../match_config.ts";
import type { MatchSim, SimEvent } from "../match_sim.ts";
import { SportRules } from "../sport_rules.ts";
import { Vector2, Vector3, clampf } from "../vec.ts";

export class SoccerRules extends SportRules {
  // Side taking the next kickoff.
  kickoff_team = 0;

  private _half_length = 20.0;
  private _half_width = 12.5;
  private _goal_half_width = 3.5;
  private _goal_height = 2.5;
  private _wall_restitution = 0.6;
  private _ball_radius = 0.11;
  private _spawn_height = 0.11;
  private _kickoff_reset_ticks = 45;

  override configure(config: MatchConfig): void {
    this._half_length = config.get_float("pitch", "length", 40.0) * 0.5;
    this._half_width = config.get_float("pitch", "width", 25.0) * 0.5;
    this._goal_half_width = config.get_float("pitch", "goal_width", 7.0) * 0.5;
    this._goal_height = config.get_float("pitch", "goal_height", 2.5);
    this._wall_restitution = config.get_float("pitch", "wall_restitution", 0.6);
    this._ball_radius = config.get_float("ball", "radius", 0.11);
    this._spawn_height = config.get_float("ball", "spawn_height", this._ball_radius);
    this._kickoff_reset_ticks = config.get_int("match", "kickoff_reset_ticks", 45);
  }

  override resolve_bounds(sim: MatchSim, events: SimEvent[]): void {
    const ball = sim.ball;
    const maxX = this._half_length - this._ball_radius;
    const maxZ = this._half_width - this._ball_radius;
    // End lines: goal if within the mouth, otherwise a cage-wall rebound.
    if (Math.abs(ball.position.x) >= maxX) {
      const attackingTeam = ball.position.x > 0.0 ? 0 : 1;
      const inGoal = Math.abs(ball.position.z) < this._goal_half_width && ball.position.y < this._goal_height;
      if (inGoal) {
        this._score_goal(sim, attackingTeam, events);
        return;
      }
      const pos = ball.position;
      ball.position = new Vector3(clampf(pos.x, -maxX, maxX), pos.y, pos.z);
      const xNormal = new Vector3(ball.position.x < 0.0 ? 1.0 : -1.0, 0.0, 0.0);
      BallPhysics.bounce(ball, xNormal, this._wall_restitution);
    }
    // Touchline walls (cage rebound).
    if (Math.abs(ball.position.z) >= maxZ) {
      const pos = ball.position;
      ball.position = new Vector3(pos.x, pos.y, clampf(pos.z, -maxZ, maxZ));
      const zNormal = new Vector3(0.0, 0.0, ball.position.z < 0.0 ? 1.0 : -1.0);
      BallPhysics.bounce(ball, zNormal, this._wall_restitution);
    }
  }

  private _score_goal(sim: MatchSim, team: number, events: SimEvent[]): void {
    sim.score[team] += 1;
    events.push({ event: "goal", team, score: { ...sim.score } });
    // Conceding team restarts (real-football kickoff).
    this.restart(sim, 1 - team);
  }

  // Reset ball to centre and players to their formation anchors (start /
  // post-goal). The kickoff team plays the first ball: opponents are held by a
  // short standoff cooldown, mirroring a real restart.
  override restart(sim: MatchSim, team: number): void {
    if (team >= 0) this.kickoff_team = team;
    sim.ball.reset(this._spawn_height);
    for (const p of sim.players) {
      p.position = p.home.copy();
      p.velocity = Vector2.ZERO;
      p.touch_cooldown = p.team === this.kickoff_team ? 0 : this._kickoff_reset_ticks;
    }
    sim.last_toucher_team = -1;
  }
}

src/sim/vec.ts:
// Godot math primitives used by the sim, ported to plain TypeScript (read-only support).
//
// Vector2 / Vector3 are VALUE types in GDScript: assignment copies them. Here they
// are small classes whose methods always return new vectors; never mutate a vector
// you did not create (use `copy()` when you need an independent value).

export const CMP_EPSILON = 0.00001;

export function clampf(value: number, min: number, max: number): number {
  return value < min ? min : value > max ? max : value;
}

export function maxf(a: number, b: number): number {
  return a > b ? a : b;
}

export function minf(a: number, b: number): number {
  return a < b ? a : b;
}

export function maxi(a: number, b: number): number {
  return a > b ? a : b;
}

export function lerpf(from: number, to: number, weight: number): number {
  return from + (to - from) * weight;
}

export function snappedf(value: number, step: number): number {
  return step !== 0 ? Math.floor(value / step + 0.5) * step : value;
}

export function isZeroApprox(value: number): boolean {
  return Math.abs(value) < CMP_EPSILON;
}

export function isEqualApprox(a: number, b: number): boolean {
  if (a === b) return true;
  let tolerance = CMP_EPSILON * Math.abs(a);
  if (tolerance < CMP_EPSILON) tolerance = CMP_EPSILON;
  return Math.abs(a - b) < tolerance;
}

// Godot's wrapf(value, min, max).
export function wrapf(value: number, min: number, max: number): number {
  const range = max - min;
  if (isZeroApprox(range)) return min;
  const result = value - range * Math.floor((value - min) / range);
  if (isEqualApprox(result, max)) return min;
  return result;
}

export class Vector2 {
  x: number;
  y: number;

  constructor(x = 0, y = 0) {
    this.x = x;
    this.y = y;
  }

  static get ZERO(): Vector2 {
    return new Vector2(0, 0);
  }

  static get RIGHT(): Vector2 {
    return new Vector2(1, 0);
  }

  copy(): Vector2 {
    return new Vector2(this.x, this.y);
  }

  add(o: Vector2): Vector2 {
    return new Vector2(this.x + o.x, this.y + o.y);
  }

  sub(o: Vector2): Vector2 {
    return new Vector2(this.x - o.x, this.y - o.y);
  }

  mul(s: number): Vector2 {
    return new Vector2(this.x * s, this.y * s);
  }

  div(s: number): Vector2 {
    return new Vector2(this.x / s, this.y / s);
  }

  neg(): Vector2 {
    return new Vector2(-this.x, -this.y);
  }

  length(): number {
    return Math.sqrt(this.x * this.x + this.y * this.y);
  }

  lengthSquared(): number {
    return this.x * this.x + this.y * this.y;
  }

  normalized(): Vector2 {
    const l = this.lengthSquared();
    if (l === 0) return new Vector2(0, 0);
    const len = Math.sqrt(l);
    return new Vector2(this.x / len, this.y / len);
  }

  dot(o: Vector2): number {
    return this.x * o.x + this.y * o.y;
  }

  // 2D cross product (z component of the 3D cross product).
  cross(o: Vector2): number {
    return this.x * o.y - this.y * o.x;
  }

  distanceTo(o: Vector2): number {
    return Math.sqrt((this.x - o.x) ** 2 + (this.y - o.y) ** 2);
  }

  distanceSquaredTo(o: Vector2): number {
    return (this.x - o.x) ** 2 + (this.y - o.y) ** 2;
  }

  moveToward(to: Vector2, delta: number): Vector2 {
    const vd = to.sub(this);
    const len = vd.length();
    return len <= delta || len < CMP_EPSILON ? to.copy() : this.add(vd.div(len).mul(delta));
  }

  angle(): number {
    return Math.atan2(this.y, this.x);
  }

  rotated(angle: number): Vector2 {
    const sine = Math.sin(angle);
    const cosi = Math.cos(angle);
    return new Vector2(this.x * cosi - this.y * sine, this.x * sine + this.y * cosi);
  }

  equals(o: Vector2): boolean {
    return this.x === o.x && this.y === o.y;
  }

  isFinite(): boolean {
    return Number.isFinite(this.x) && Number.isFinite(this.y);
  }
}

export class Vector3 {
  x: number;
  y: number;
  z: number;

  constructor(x = 0, y = 0, z = 0) {
    this.x = x;
    this.y = y;
    this.z = z;
  }

  static get ZERO(): Vector3 {
    return new Vector3(0, 0, 0);
  }

  static get UP(): Vector3 {
    return new Vector3(0, 1, 0);
  }

  copy(): Vector3 {
    return new Vector3(this.x, this.y, this.z);
  }

  add(o: Vector3): Vector3 {
    return new Vector3(this.x + o.x, this.y + o.y, this.z + o.z);
  }

  sub(o: Vector3): Vector3 {
    return new Vector3(this.x - o.x, this.y - o.y, this.z - o.z);
  }

  mul(s: number): Vector3 {
    return new Vector3(this.x * s, this.y * s, this.z * s);
  }

  length(): number {
    return Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z);
  }

  normalized(): Vector3 {
    const l = this.x * this.x + this.y * this.y + this.z * this.z;
    if (l === 0) return new Vector3(0, 0, 0);
    const len = Math.sqrt(l);
    return new Vector3(this.x / len, this.y / len, this.z / len);
  }

  dot(o: Vector3): number {
    return this.x * o.x + this.y * o.y + this.z * o.z;
  }

  cross(o: Vector3): Vector3 {
    return new Vector3(
      this.y * o.z - this.z * o.y,
      this.z * o.x - this.x * o.z,
      this.x * o.y - this.y * o.x,
    );
  }

  equals(o: Vector3): boolean {
    return this.x === o.x && this.y === o.y && this.z === o.z;
  }

  isZero(): boolean {
    return this.x === 0 && this.y === 0 && this.z === 0;
  }

  isFinite(): boolean {
    return Number.isFinite(this.x) && Number.isFinite(this.y) && Number.isFinite(this.z);
  }
}
